package dev.colonyhorizons.client.supply;
import com.ldtteam.blockui.controls.*;
import dev.colonyhorizons.network.SupplyMenuPayloads.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import java.util.*;
/** One small decision per page; editing a review requires another server review. */
public final class WindowRemoteFounding extends WindowSupplyBase {
 private final CompoundTag form=new CompoundTag();private final ListTag budget=new ListTag();private CompoundTag selectedItem;private int step,page;private boolean requested,reviewing;
 public WindowRemoteFounding(){super("founding");form.putString("name","Forestry Outpost");form.putInt("cap",1);form.put("budget",budget);}
 private String field(String id){return findPaneOfTypeByID(id,TextField.class).getText().trim();}
 private void set(String id,String value){findPaneOfTypeByID(id,TextField.class).setText(value);}
 @Override public void onOpened(){super.onOpened();set("name",form.getString("name"));var player=net.minecraft.client.Minecraft.getInstance().player;var pos=player==null?BlockPos.ZERO:player.blockPosition();set("x",""+pos.getX());set("y",""+pos.getY());set("z",""+pos.getZ());if(!requested){requested=true;fetch();}}
 private void fetch(){var request=new CompoundTag();request.putString("kind",step==0?"warehouses":step==1?"citizens":"budget");request.putInt("page",page);request.putLong("home",form.getLong("home"));SupplyMenuClient.remote(Action.REMOTE_OPTIONS,request,new UUID(0,0));render();}
 String rowText(CompoundTag r){if(step==4)return r.getString("name")+": need "+r.getInt("needed")+", allowed "+r.getInt("allowance");if(step==3)return r.getString("name")+" | Home: "+r.getInt("stock");return(form.contains("home")&&form.getLong("home")==r.getLong("pos")?"Selected: ":"")+r.getString("name")+" "+BlockPos.of(r.getLong("pos")).toShortString();}
 void select(CompoundTag r){if(SupplyMenuClient.pending)return;try{if(step==0)form.putLong("home",r.getLong("pos"));else if(step==3){saveItem();selectedItem=r.copy();var entry=entry(r);set("allowance",Integer.toString(entry==null?0:entry.getInt("allowance")));set("reserve",Integer.toString(entry==null?0:entry.getInt("reserve")));text("message",r.getString("name"));}render();}catch(IllegalArgumentException e){text("message",e.getMessage());}}
 private CompoundTag entry(CompoundTag row){for(var value:budget){var t=(CompoundTag)value;if(t.get("item").equals(row.get("item")))return t;}return null;}
 private void saveItem(){if(selectedItem==null)return;int allowance=Integer.parseInt(field("allowance")),reserve=Integer.parseInt(field("reserve"));if(allowance<0||reserve<0||allowance>1000000||reserve>1000000)throw new IllegalArgumentException("Use amounts from 0 to 1000000");var item=entry(selectedItem);if(item==null){if(budget.size()>=128)throw new IllegalArgumentException("Maximum 128 allowance items");item=new CompoundTag();item.put("item",selectedItem.get("item").copy());budget.add(item);}item.putInt("allowance",allowance);item.putInt("reserve",reserve);}
 void render(){text("title","Found Outpost - "+List.of("Home Warehouse","Founders","Site","Supply Allowance","Review").get(step));for(String id:List.of("name","x","y","z"))findPaneByID(id).setVisible(step==2);findPaneByID("entries").setVisible(step!=2);for(String id:List.of("allowance","reserve","allowLabels","pageStock"))findPaneByID(id).setVisible(step==3);findPaneByID("mode").setVisible(step==2);findPaneByID("cap").setVisible(step==2);label("mode",form.getBoolean("automatic")?"Automatic in limits":"Ask before expanding");label("cap","Level cap: "+form.getInt("cap"));
  if(step!=2)showRows(step==4?SupplyMenuClient.data.getCompound("remoteReview").getList("costs",10):SupplyMenuClient.data.getCompound("remoteChoices").getList("entries",10));
  text("hint",switch(step){case 0->"Supplies travel between warehouses. Couriers work locally.";case 1->"Four settlers included.";case 2->"Name and floor X / Y / Z. Visit and clear a supported remote site first.";case 3->"Choose an item: total allowance / amount to leave at Home.";default->"4 free settlers: Mayor, Builder, Courier, Forester. Eight buildings.";});
  label("continue",step==4?"Approve Founding":step==3?"Review":"Continue");enable("continue",step==0?form.contains("home"):step!=4||SupplyMenuClient.data.getCompound("remoteReview").getBoolean("ready"));enable("previous",step>0);enable("prev",page>0&&step!=2&&step!=4);enable("next",step!=2&&step!=4&&SupplyMenuClient.data.getCompound("remoteChoices").getBoolean("next"));enable("mode",true);enable("cap",true);enable("pageStock",true);
  if(step==4){var r=SupplyMenuClient.data.getCompound("remoteReview");text("message",!r.getString("problem").isBlank()?r.getString("problem"):r.getBoolean("ready")?"Review all founding costs below. Later work uses the remaining allowance.":"Founding allowance is short. Go back to supplies; nothing has been spent.");}
 }
 @Override public void reply(MenuReply reply){if(reply.ok()&&reply.message().equals("Founding approved")){SupplyMenuClient.show(new WindowMayor(reply.data().getCompound("mayor").getUUID("id")));return;}if(reviewing){reviewing=false;if(reply.ok())step=4;}super.reply(reply);if(step==4)render();}
 @Override public void onButtonClicked(Button b){if(b.getID().equals("back")){if(SupplyMenuClient.pending)SupplyMenuClient.finish();else SupplyMenuClient.show(new WindowOutpostsSupplies());return;}if(SupplyMenuClient.pending)return;try{switch(b.getID()){
  case "mode"->form.putBoolean("automatic",!form.getBoolean("automatic"));case "cap"->form.putInt("cap",form.getInt("cap")%5+1);
  case "prev","next"->{saveItem();selectedItem=null;page+=b.getID().equals("next")?1:-1;fetch();}
  case "previous"->{saveItem();selectedItem=null;step=step==2?0:step-1;page=0;if(step!=2)fetch();}
  case "pageStock"->{saveItem();selectedItem=null;for(var r:rows){var e=entry(r);if(e==null){if(budget.size()>=128)throw new IllegalArgumentException("Maximum 128 allowance items");e=new CompoundTag();e.put("item",r.get("item").copy());budget.add(e);}e.putInt("allowance",r.getInt("stock"));e.putInt("reserve",0);}text("message","Allowed the finite stock shown on this page. Review before approval.");}
  case "continue"->{if(step==4){SupplyMenuClient.send(Action.APPROVE_REMOTE,new UUID(0,0));break;}if(step==2){form.putString("name",field("name"));form.putLong("center",dev.colonyhorizons.menu.RemoteMenuInput.center(field("x"),field("y"),field("z")).asLong());}if(step==3){saveItem();form.put("budget",budget.copy());reviewing=true;SupplyMenuClient.remote(Action.REVIEW_REMOTE,form,new UUID(0,0));}else{step=step==0?2:step+1;page=0;if(step!=2)fetch();}}
  default->{} }render();}catch(IllegalArgumentException e){text("message",e instanceof NumberFormatException?"Enter whole numbers for coordinates and supplies.":e.getMessage());}}
}
